import pandas as pd

def count_passengers_in_bus(buses: pd.DataFrame, passengers: pd.DataFrame) -> pd.DataFrame:
    if passengers.empty:
        result = buses[['bus_id']].copy()
        result['passengers_cnt'] = 0
        return result.sort_values('bus_id')
    merged = passengers.merge(buses, how='cross')
    valid = merged[merged['arrival_time_x'] <= merged['arrival_time_y']]
    if valid.empty:
        result = buses[['bus_id']].copy()
        result['passengers_cnt'] = 0
        return result.sort_values('bus_id')
    earliest = valid.groupby('passenger_id')['arrival_time_y'].min().reset_index()
    counts = earliest['arrival_time_y'].value_counts().reset_index()
    counts.columns = ['arrival_time', 'passengers_cnt']
    res = buses.merge(counts, on='arrival_time', how='left')
    res['passengers_cnt'] = res['passengers_cnt'].fillna(0).astype(int)
    return res[['bus_id', 'passengers_cnt']].sort_values('bus_id')
